# Created: 2026-08-01

"""How a record's content is read — one vocabulary, both stages (plan D3, T4.0).

This was Stage 2's, in `stage2/state.py`, because Stage 2 was the first thing that needed to say
"this record was not touched". Stage 1 needs the same sentence for `seeded_tree`, and Stage 1
importing Stage 2 would invert the layering — `stage2` already imports `harness`, and D3's whole
point is that there is one oracle vocabulary rather than four. So it moved down a layer. Nothing
about the Stage-2 signatures changed in the move; `stage2/state.py` imports them from here.

Two entry points, deliberately different, because they answer different questions:

* `signature()` is Stage 2's. It asks "was this bystander touched by the call under grading",
  and its per-namespace choices are argued in the functions below — `family_list` is out of the
  person signature on purpose, and notes and tags fall through to the person shape because no
  class-A check addresses their content. Behaviour preserved exactly; changing it would change
  what a paid sweep reports.
* `content_signature()` is Stage 1's. It asks "is this still the tree we seeded", so it covers
  every namespace the suite writes to and includes what the grader can afford to ignore: a note's
  text, a tag's name, a family's event refs — that last one because a whole-object family PUT can
  drop `event_ref_list` (`gramps_client.py:933`) without moving any count, and a reset that could
  not see that would hand the next class a tree with a severed marriage.

What neither can see: an object edited in place in a namespace that carries no signature —
citations, events, media, places, repositories. Measured 2026-08-01: no tool in this server edits
one, they are only created and deleted, so `object_counts` is a sufficient witness for them and
the digest carries the counts alongside the signatures.
"""

from __future__ import annotations

from collections.abc import Mapping
from typing import Any

# The namespaces that carry a content signature. The rest are covered by their counts.
SIGNED = ("people", "families", "sources", "notes", "tags")


# -- reading one field off a record -------------------------------------------------------


def first_name(person: Mapping[str, Any]) -> str:
    return str((person.get("primary_name") or {}).get("first_name", ""))


def surname(person: Mapping[str, Any]) -> str:
    return name_surname(person.get("primary_name") or {})


def name_surname(name: Mapping[str, Any]) -> str:
    entries = name.get("surname_list") or []
    return str(entries[0].get("surname", "")) if entries else ""


def name_type(name: Mapping[str, Any]) -> str:
    """Measured 2026-07-31: the API answers with a bare string (`"Married Name"`)."""
    return str(name.get("type", ""))


def note_text(note: Mapping[str, Any]) -> str:
    """Measured (plan §5): `note["text"]` is `{"string": …, "tags": []}`, not a string."""
    return str((note.get("text") or {}).get("string", ""))


def members(family: Mapping[str, Any], ids: Mapping[str, str]) -> list[str]:
    """Both parent slots, as ids. Never *which* slot — that assignment is what uc2 tests."""
    return sorted(
        ids[handle]
        for handle in (family.get("father_handle"), family.get("mother_handle"))
        if handle and handle in ids
    )


def children(family: Mapping[str, Any], ids: Mapping[str, str]) -> list[str]:
    return sorted(
        ids[str(ref.get("ref", ""))]
        for ref in family.get("child_ref_list") or []
        if str(ref.get("ref", "")) in ids
    )


def tag_names(record: Mapping[str, Any], tags: Mapping[str, str]) -> tuple[str, ...]:
    """A record's tags by name.

    By name and not by handle on purpose: an import re-creates an identical tag as a *new*
    object (measured — uc19's import brings its own `Unbestätigt` and Gramps does not merge),
    and a bystander whose tag handle moved underneath them has not been touched by the call.
    """
    return tuple(sorted(tags[handle] for handle in record.get("tag_list") or [] if handle in tags))


# -- what "this record was not touched" means, per namespace --------------------------------


def person_signature(person: Mapping[str, Any], tags: Mapping[str, str]) -> tuple[Any, ...]:
    """What "this person was not touched" means.

    `family_list` is deliberately **not** in it. Deleting a family rewrites the membership of
    both spouses, and uc16 does exactly that on purpose; including it would red every bystander
    of a legitimate call. Family membership is asserted where it is the point, by the `family`
    kind, against named subjects.
    """
    alternates = tuple(
        (name_surname(name), name_type(name)) for name in person.get("alternate_names") or []
    )
    return (
        first_name(person),
        surname(person),
        name_type(person.get("primary_name") or {}),
        person.get("gender"),
        tag_names(person, tags),
        alternates,
    )


def family_signature(family: Mapping[str, Any], ids: Mapping[str, str]) -> tuple[Any, ...]:
    """Both parent slots *and* which slot each sits in: a swap is a change, and uc2 says so."""
    return (
        ids.get(str(family.get("father_handle") or ""), ""),
        ids.get(str(family.get("mother_handle") or ""), ""),
        tuple(children(family, ids)),
    )


def source_signature(source: Mapping[str, Any], tags: Mapping[str, str]) -> tuple[Any, ...]:
    """Title, author and which notes hang off it — the note's *text* belongs to the note."""
    return (
        source.get("title", ""),
        source.get("author", ""),
        tuple(source.get("note_list") or []),
        tag_names(source, tags),
    )


def note_signature(note: Mapping[str, Any], tags: Mapping[str, str]) -> tuple[Any, ...]:
    """The text itself. `update_blog_post` rewrites a note in place and moves nothing else —
    no count, no handle, no id — so a reset that reads only identity hands the next class a
    tree whose article says something different."""
    return (note_text(note), str(note.get("type", "")), tag_names(note, tags))


def tag_signature(tag: Mapping[str, Any], _tags: Mapping[str, str]) -> tuple[Any, ...]:
    """Tags are matched by name everywhere in this suite, so the name is the content."""
    return (str(tag.get("name", "")),)


def signature(
    namespace: str, record: Mapping[str, Any], tags: Mapping[str, str]
) -> tuple[Any, ...]:
    """What "this record was not touched" means, per namespace — **Stage 2's** answer.

    `people` needs the handle→id map for nothing, `families` needs it for everything; the map is
    rebuilt from the record's own capture by the caller that holds it.
    """
    if namespace == "families":
        return family_signature(record, _ids_of(record))
    if namespace == "sources":
        return source_signature(record, tags)
    return person_signature(record, tags)


def content_signature(
    namespace: str, record: Mapping[str, Any], tags: Mapping[str, str]
) -> tuple[Any, ...]:
    """**Stage 1's** answer: every signed namespace, and nothing falls through to a shape that
    happens to parse. An unknown namespace raises rather than digesting to `("", "", …)` —
    a silent empty signature is a digest that agrees with any drift at all."""
    if namespace == "families":
        return family_signature(record, _ids_of(record)) + (
            tuple(str(ref.get("ref", "")) for ref in record.get("event_ref_list") or []),
        )
    return {
        "people": person_signature,
        "sources": source_signature,
        "notes": note_signature,
        "tags": tag_signature,
    }[namespace](record, tags)


def _ids_of(family: Mapping[str, Any]) -> dict[str, str]:
    """Families are compared by *handle* rather than id: the map belongs to a capture, and a
    signature is per record. Handles are stable across a call, which is the property needed."""
    return {
        handle: handle
        for handle in (
            str(family.get("father_handle") or ""),
            str(family.get("mother_handle") or ""),
            *(str(ref.get("ref", "")) for ref in family.get("child_ref_list") or []),
        )
        if handle
    }
